void DebugScreenViewBase::setupScreen()
{
    battery_cells.initialize();
    for (int i = 0; i < battery_cellsListItems.getNumberOfDrawables(); i++)
    {
        battery_cellsListItems[i].initialize();
    }
    batteryProgressBar.initialize();
}

void DebugScreenViewBase::updateItemCallbackHandler(touchgfx::DrawableListItemsInterface* items, int16_t containerIndex, int16_t itemIndex)
{
    if (items == &battery_cellsListItems)
    {
        battery_cellsUpdateItem(battery_cellsListItems[containerIndex], itemIndex);
    }
}
